/*
 * The design tokens for Katalyst.
 *
 * This file is the whole visual vocabulary of the product in one place: every
 * colour, size, weight, space and duration the interface is allowed to use.
 * Nothing else in the app writes a raw colour or a raw pixel number. Later work
 * — the workbench canvas with its proposition tiles and causal wires — inherits
 * these same names, so the first screen and the finished product cannot drift
 * apart visually.
 *
 * Which product rules this serves (from PRODUCT_REQUIREMENTS.md section 7):
 *
 *   UX-6  "Colour is law."  Direction of financial effect is blue for up and
 *         amber for down, never red and green, and always carried by a glyph
 *         and a word as well as a hue. Tail risk (a rare, large outcome) is a
 *         hatched texture rather than a colour, because texture survives every
 *         kind of colour blindness and survives inverting light and dark.
 *   UX-7  "Motion budget."  On this screen there is exactly one animation: a
 *         placeholder fading into the value that replaced it. One duration
 *         token controls it, and it becomes instant when the operating system
 *         asks for reduced motion.
 *   UX-11 "Typography."  One interface typeface, one monospace typeface with
 *         fixed-width digits for every number, exactly three sizes and exactly
 *         three weights. Hierarchy comes from colour and spacing, not size.
 *   UX-12 "Themes and access."  Dark is the default; a light theme is defined
 *         too. Every piece of text clears a contrast ratio of 4.5 to 1 against
 *         the surface behind it, in both themes. The ratios are written beside
 *         each colour below.
 *
 * How the two themes are chosen:
 *   - The page ships dark, because `index.html` sets `data-theme="dark"` on the
 *     html element. That attribute wins over everything else.
 *   - `data-theme="light"` forces the light theme.
 *   - Remove the attribute and the page follows the operating system: dark
 *     unless the operating system asks for light.
 */

:root {
  /* ---- Typefaces ------------------------------------------------------ *
   * Inter for the interface and JetBrains Mono for every number.
   *
   * Why this pair, and not Geist: both are shipped as ordinary npm packages
   * (`@fontsource-variable/...`) that carry the font files themselves, so the
   * app draws its first frame with no request to any outside service and works
   * with no network at all inside a container. The `geist` package publishes
   * its fonts only through the Next.js font loader, which this app does not
   * use. Inter is a neutral interface face that stays legible at 13 pixels;
   * JetBrains Mono has fixed-width digits, so a number that changes does not
   * make the column beside it jump sideways.
   *
   * The system fallbacks after each name are what a browser draws in the
   * fraction of a second before the font file arrives. */
  --font-interface:
    "Inter Variable", ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono Variable", ui-monospace, "SF Mono", "Cascadia Mono", monospace;

  /* ---- Type scale: exactly three sizes, exactly three weights --------- *
   * 13 / 15 / 22 pixels. A fourth size is not a small addition; it is a new
   * rule everything afterwards has to obey, so there are three. */
  --text-sm: 13px;
  --text-md: 15px;
  --text-lg: 22px;

  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;

  /* ---- Spacing: an eight-pixel grid ----------------------------------- *
   * Every margin, padding and gap is one of these. `--space-hair` is the one
   * half-step, for the gap between a glyph and the word beside it. */
  --space-hair: 4px;
  --space-1: 8px;
  --space-2: 16px;
  --space-3: 24px;
  --space-4: 32px;
  --space-5: 48px;
  --space-6: 64px;

  --radius: 6px;

  /* ---- Motion --------------------------------------------------------- *
   * One duration, used only for opacity. Nothing here moves position, scales,
   * bounces or loops. */
  --duration-fast: 120ms;

  /* ---- Dark theme: the default ---------------------------------------- *
   * Contrast ratios below are measured against `--surface` (#0E1116), whose
   * own ratio against white is 18.9 to 1. It is a very dark blue-grey rather
   * than pure black: pure black against bright text vibrates at small sizes,
   * and leaves no darker shade to fall back on. */
  color-scheme: dark;

  --surface: #0e1116;
  /* The page behind everything. */
  --surface-raised: #151a21;
  /* A panel sitting on the page: lighter, no shadow. */
  --hairline: rgb(233 237 243 / 10%);
  /* A one-pixel border at 10% of the text colour. Separation without chrome. */

  --text: #e9edf3;
  /* 16.1 to 1 on --surface, 14.9 to 1 on --surface-raised. */
  --text-muted: #98a2b1;
  /* 7.3 to 1 on --surface, 6.8 to 1 on --surface-raised. Quiet, still readable. */

  --accent: #5fd4c4;
  /* 10.5 to 1 on --surface. A teal used sparingly — a state glyph, the mark in
   * the icon. Deliberately not the same hue as --dir-up, so that "this is fine"
   * can never be mistaken for "this moves the position up". */

  --dir-up: #6fb3ff;
  /* 8.6 to 1 on --surface. Financial effect upward. Always drawn with an
   * upward glyph and a sign as well (UX-6, and invariant INV-12). */
  --dir-down: #f0b23c;
  /* 10.0 to 1 on --surface. Financial effect downward. Blue and amber, never
   * red and green: red-green fails the most common form of colour blindness,
   * and carries loss-and-gain baggage that is wrong half the time. */

  --tail: repeating-linear-gradient(
    45deg,
    rgb(233 237 243 / 0%) 0 3px,
    rgb(233 237 243 / 28%) 3px 4px
  );
  /* Tail risk — a rare outcome large enough to matter — is marked with this
   * diagonal hatch, never with a colour. A texture is still a texture in
   * greyscale, in a screenshot, and to a colour-blind reader. */

  --focus: #7ce0d0;
  /* The ring drawn around whatever the keyboard is on. Bright enough to find at
   * a glance: 12.1 to 1 on --surface, far above the 3 to 1 a non-text mark
   * needs. */

  /* ==== THE COLOUR LAW: ADDED FOR THE WIRES AND THE PANEL ================ *
   * Everything from here to the end of this block is new. No value above it
   * changed.
   *
   * The organising rule is **one channel per meaning**. A channel is one thing
   * the eye can vary on its own — brightness, hue, texture, stroke pattern,
   * stroke width, shape, position. Six meanings, six channels, and no channel
   * doing two jobs, because every failure in this area is two meanings
   * fighting over one channel.
   *
   *   how likely a claim is  -> brightness, the five-step ramp below
   *   which way money moves   -> hue, --dir-up and --dir-down above, never alone
   *   tail risk               -> texture, --tail above
   *   what kind of push       -> the wire's stroke: pattern, width, doubling
   *   where an arrow came from-> a mark of one, two or three dots at its tail
   *   which branch you are in -> the four branch hues below, plus a name chip
   *
   * Only the first and the last are colours defined here. The stroke and the
   * mark are deliberately colourless: every wire is drawn in --text-muted, and
   * a wire's hue says nothing at all. */

  /* ---- How likely a claim is: a five-step neutral ramp ----------------- *
   * Five brightnesses of the same blue-grey as the surface. Neutral on
   * purpose: any hue in here would be a second voice in the channel that means
   * "which way the money moves".
   *
   *   --p-0  0 to under .2      --p-3  .6 to under .8
   *   --p-1  .2 to under .4     --p-4  .8 to 1
   *   --p-2  .4 to under .6
   *
   * Three rules on it. It never carries text — a number is always drawn in
   * --text, so it always clears 4.5 to 1, while the ramp paints a bar, which
   * is a graphic and needs 3 to 1. It never paints a whole tile, because
   * tile-wide brightness is already spent on the old world in a diff and on
   * the hover lens. And five steps are a glance, never a reading: the exact
   * number and its range are printed beside the bar every time.
   *
   * Ratios below are measured against --surface-raised, the panel a bar is
   * drawn on, and then against --surface. The lowest step clears 3 to 1, so
   * even a bar for an unlikely claim is a bar somebody can see. */
  --p-0: #646a73;
  /* 3.2 to 1 on --surface-raised, 3.5 to 1 on --surface. */
  --p-1: #7f858e;
  /* 4.7 to 1 on --surface-raised, 5.1 to 1 on --surface. */
  --p-2: #9ba1a9;
  /* 6.7 to 1 on --surface-raised, 7.3 to 1 on --surface. */
  --p-3: #b9bdc5;
  /* 9.3 to 1 on --surface-raised, 10.0 to 1 on --surface. */
  --p-4: #d5dae0;
  /* 12.4 to 1 on --surface-raised, 13.4 to 1 on --surface. */

  /* ---- What kind of push an arrow is: the four stroke widths ----------- *
   * Width comes from the size of a push regardless of its sign. Four steps,
   * not a continuous ramp, because a fifth is not tellable apart at a
   * hairline. Which step a push lands in is a comparison against three
   * thresholds — a lookup, not arithmetic — and the thresholds are written
   * down in `graph/wires/encodings.ts` beside the words they pair with. */
  --wire-1: 1px;
  --wire-2: 2px;
  --wire-3: 3px;
  --wire-4: 4px;
  /* The clear gap down the middle of a wire that has to keep holding. A
   * `sustain` wire is drawn as two parallel strokes with this between them; a
   * `trigger` wire is a single stroke. */
  --wire-gap: 2px;

  /* ---- Which branch you are in ---------------------------------------- *
   * Four hues, used only on a branch's lane and its chips and never on a
   * tile's meaning. Every branch also carries a name chip with its label, so a
   * branch is readable with no colour at all.
   *
   * **Not amber.** Amber already means "the money moves down", and one hue
   * cannot mean two things.
   *
   * Nothing in this build draws a branch — the branch panel is the next piece
   * of work — so these four are defined and unused. They are written now so
   * that nobody borrows a direction hue for a lane in the meantime.
   *
   * The teal is deliberately darker and bluer than --accent and --focus, which
   * are also teals. See the note in `styles/__tests__/colourLaw.test.ts`. */
  --branch-violet: #b193f2;
  /* 7.5 to 1 on --surface, 6.9 to 1 on --surface-raised. */
  --branch-teal: #2f93b0;
  /* 5.3 to 1 on --surface, 4.9 to 1 on --surface-raised. */
  --branch-rose: #f18aa6;
  /* 8.0 to 1 on --surface, 7.4 to 1 on --surface-raised. */
  --branch-slate: #98a8c2;
  /* 7.8 to 1 on --surface, 7.3 to 1 on --surface-raised. */

  /* ---- Two more durations --------------------------------------------- *
   * The motion budget is three moves and no more: wires drawing in causal
   * order, a branch arriving, and a likelihood rolling from its old figure to
   * its new one. Everything else is an opacity change of at most
   * --duration-fast.
   *
   * Nothing in this build spends either of these yet — no wire draws itself in
   * and no number moves. They are named here because the ordering below, under
   * reduced motion, is a rule about them: the tweening goes and the ordering
   * stays, because the ordering is the causality. */
  --duration-wave: 200ms;
  --duration-stagger: 60ms;
}

/* Light theme, forced by the html element's data-theme attribute. */
[data-theme="light"] {
  color-scheme: light;

  --surface: #f7f8fa;
  --surface-raised: #ffffff;
  --hairline: rgb(16 20 26 / 10%);

  --text: #10141a;
  /* 17.4 to 1 on --surface, 18.5 to 1 on --surface-raised. */
  --text-muted: #5b6577;
  /* 5.5 to 1 on --surface, 5.9 to 1 on --surface-raised. */

  --accent: #0f766e;
  /* 5.2 to 1 on --surface, 5.5 to 1 on --surface-raised. */

  --dir-up: #1f5fcc;
  /* 5.5 to 1 on --surface, 5.9 to 1 on --surface-raised. */
  --dir-down: #96590a;
  /* 5.3 to 1 on --surface, 5.6 to 1 on --surface-raised. Amber has to go dark
   * and slightly brown on a white page to clear 4.5 to 1; the glyph and the
   * word carry the meaning either way. */

  --tail: repeating-linear-gradient(45deg, rgb(16 20 26 / 0%) 0 3px, rgb(16 20 26 / 24%) 3px 4px);

  --focus: #0d6e66;
  /* 5.7 to 1 on --surface. */

  /* ==== THE COLOUR LAW, IN LIGHT ========================================= *
   * The ramp runs the other way here, and that is the point rather than an
   * oversight. On a near-black page a more likely claim is a brighter bar; on
   * a white page a brighter bar would be a bar you cannot see. What is
   * constant in both themes is what the eye actually reads: **more likely is
   * more contrast against the page.** So the light ramp goes from the faintest
   * step a reader can still see up to nearly the text colour.
   *
   * Every step clears 3 to 1 against both surfaces, which is what a bar — a
   * graphic rather than a word — has to clear. */
  --p-0: #868c97;
  /* 3.2 to 1 on --surface, 3.4 to 1 on --surface-raised. */
  --p-1: #6e747f;
  /* 4.4 to 1 on --surface, 4.7 to 1 on --surface-raised. */
  --p-2: #565c66;
  /* 6.3 to 1 on --surface, 6.7 to 1 on --surface-raised. */
  --p-3: #414851;
  /* 8.7 to 1 on --surface, 9.2 to 1 on --surface-raised. */
  --p-4: #2e353e;
  /* 11.7 to 1 on --surface, 12.4 to 1 on --surface-raised. */

  --branch-violet: #6338c4;
  /* 6.8 to 1 on --surface, 7.3 to 1 on --surface-raised. */
  --branch-teal: #0a5a72;
  /* 7.2 to 1 on --surface, 7.7 to 1 on --surface-raised. */
  --branch-rose: #a32f52;
  /* 6.4 to 1 on --surface, 6.8 to 1 on --surface-raised. */
  --branch-slate: #44527a;
  /* 7.2 to 1 on --surface, 7.7 to 1 on --surface-raised. */
}

/* No data-theme attribute at all: follow the operating system. Dark stays the
 * default, because only an explicit request for light lands here. */
@media (prefers-color-scheme: light) {
  :root:not([data-theme="dark"]) {
    color-scheme: light;

    --surface: #f7f8fa;
    --surface-raised: #ffffff;
    --hairline: rgb(16 20 26 / 10%);

    --text: #10141a;
    --text-muted: #5b6577;

    --accent: #0f766e;

    --dir-up: #1f5fcc;
    --dir-down: #96590a;

    --tail: repeating-linear-gradient(45deg, rgb(16 20 26 / 0%) 0 3px, rgb(16 20 26 / 24%) 3px 4px);

    --focus: #0d6e66;

    /* The colour law in light, repeated here for the reader who has asked for
     * no theme at all and whose operating system asks for a light page. Same
     * values as the forced light theme above, and the same reason: more likely
     * is more contrast against the page. */
    --p-0: #868c97;
    --p-1: #6e747f;
    --p-2: #565c66;
    --p-3: #414851;
    --p-4: #2e353e;

    --branch-violet: #6338c4;
    --branch-teal: #0a5a72;
    --branch-rose: #a32f52;
    --branch-slate: #44527a;
  }
}

/* When the operating system asks for less movement, the tweening goes and the
 * ordering stays (UX-7).
 *
 * *Tweening* is the in-between frames that make a change look like a movement.
 * Those go: a value still replaces the placeholder, and a wire still arrives,
 * but neither takes any time doing it. What does **not** go is
 * `--duration-stagger`, the gap between one layer of the map and the next,
 * because that gap is the order the argument runs in — the ordering is the
 * causality, and removing it would remove the one thing the movement was for. */
@media (prefers-reduced-motion: reduce) {
  :root {
    --duration-fast: 0ms;
    --duration-wave: 0ms;
  }
}

