1	/*
2	 * The tile.
3	 *
4	 * Two rules run through all of it. First, everything sits on the eight-pixel
5	 * grid and takes its colour, its type and its spacing from `tokens.css`; there
6	 * are two raw numbers below and both are commented where they appear. Second,
7	 * there are no shadows anywhere — separation comes from a one-pixel line at a
8	 * tenth of the text colour, which is drawn as part of the tile's outline rather
9	 * than as a border, so that a hypothesis and a dead end can be different shapes.
10	 */
11	
12	.tile {
13	  position: relative;
14	  display: flex;
15	  flex-direction: column;
16	  gap: var(--space-1);
17	  /* Twelve pixels of internal padding, settled. It is one and a half steps of
18	   * the eight-pixel grid: the grid governs where things sit relative to each
19	   * other, and twelve is the distance from the drawn outline to the first word,
20	   * which wants to be tighter than sixteen and looser than eight. */
21	  padding: 12px;
22	  font-family: var(--font-interface);
23	  color: var(--text);
24	  /* No background of its own: the drawn outline below fills the shape, so the
25	   * fill follows the shape exactly rather than squaring off its corners. */
26	  background: none;
27	  /* The tile's own words may leave its box — the shelf a belief chip opens
28	   * hangs below it — so nothing here clips. */
29	  overflow: visible;
30	  /* The tile stacks its own parts among themselves and not among its
31	   * neighbours' parts. Without this the drawn outline below, which has to sit
32	   * behind the words, would sink behind the map itself and take the tile's fill
33	   * with it. */
34	  isolation: isolate;
35	}
36	
37	/* Nothing inside a tile is ever squeezed. The tile's height was worked out from
38	 * exactly these blocks, so if the arithmetic is a fraction of a pixel out the
39	 * right answer is for the tile to be a fraction of a pixel taller — not for the
40	 * claim to lose the bottom of its last line, which is what a flexible box does
41	 * by default and which reads as text cut in half. */
42	.tile__header,
43	.tile__claim,
44	.tile__beliefs,
45	.tile__foot {
46	  flex: none;
47	}
48	
49	/* The drawn outline: the fill and the one-pixel line, in the shape that says
50	 * what kind of claim this is. Sits behind everything in the tile, and takes no
51	 * clicks. */
52	.tile__outline {
53	  position: absolute;
54	  inset: 0;
55	  z-index: -1;
56	  pointer-events: none;
57	}
58	
59	.tile__outline path {
60	  fill: var(--surface-raised);
61	  stroke: var(--hairline);
62	  stroke-width: 1;
63	}
64	
65	/* Two of the four outlines cut into the tile on one side — the hypothesis comes
66	 * to a point on the left, the dead end is notched on the right — so those two
67	 * tiles hold their words a step further from that edge. Nothing is ever drawn
68	 * across a word. */
69	.tile[data-kind="hypothesis"] {
70	  padding-left: var(--space-3);
71	}
72	
73	.tile[data-kind="not_tradeable"] {
74	  padding-right: var(--space-3);
75	}
76	
77	/* The claim the reader started from is the one thing on the map that did not
78	 * come from the model, so its outline is drawn in the accent rather than in the
79	 * hairline. The shape already says it is the hypothesis; this only makes the
80	 * eye land there first. */
81	.tile[data-hypothesis="yes"] .tile__outline path {
82	  stroke: var(--accent);
83	}
84	
85	/* ---- The header: what kind of claim, and when it settles ---------------- */
86	
87	.tile__header {
88	  display: flex;
89	  align-items: baseline;
90	  justify-content: space-between;
91	  gap: var(--space-1);
92	  font-size: var(--text-sm);
93	  color: var(--text-muted);
94	  min-width: 0;
95	}
96	
97	.tile__kind {
98	  font-weight: var(--weight-medium);
99	  letter-spacing: 0.04em;
100	  white-space: nowrap;
101	}
102	
103	.tile__resolves {
104	  font-family: var(--font-mono);
105	  font-variant-numeric: tabular-nums;
106	  white-space: nowrap;
107	}
108	
109	/* ---- The claim ---------------------------------------------------------- *
110	 * As many lines as the tile was built to hold — at most three — and then it
111	 * stops. The number comes from the same place the tile's height came from, so
112	 * the claim stops exactly where the box ends and never a line later. The stop
113	 * is by line rather than by character, so a word is never cut in half to save a
114	 * few pixels; the rest of the sentence lives in the panel beside the map. */
115	
116	.tile__claim {
117	  margin: 0;
118	  font-size: var(--text-md);
119	  line-height: 1.35;
120	  color: var(--text);
121	  text-wrap: pretty;
122	  display: -webkit-box;
123	  -webkit-box-orient: vertical;
124	  -webkit-line-clamp: var(--tile-claim-lines, 3);
125	  line-clamp: var(--tile-claim-lines, 3);
126	  overflow: hidden;
127	}
128	
129	/* ---- The beliefs -------------------------------------------------------- *
130	 * Side by side, equal widths, with a hairline between them. One column per
131	 * owner who has something to say: the model always, and the reader and a venue
132	 * where they hold a number. They are never merged into one number — the shape
133	 * of the row is the argument — and a column with nothing in it is not drawn.
134	 *
135	 * The columns are made by the chips rather than declared as three, so the row
136	 * shares its whole width between whichever of them are there: one chip fills
137	 * the tile, two take half each, three take a third each exactly as before.
138	 * **The tile does not change size either way.** Its height and its width are
139	 * written on its own box from `geometry.ts`, which reserves the same rail
140	 * whatever the chips hold — so a number arriving later widens the survivors and
141	 * re-lays out nothing. */
142	
143	.tile__beliefs {
144	  display: grid;
145	  grid-auto-flow: column;
146	  grid-auto-columns: minmax(0, 1fr);
147	  column-gap: var(--space-1);
148	  padding-top: var(--space-1);
149	  border-top: 1px solid var(--hairline);
150	}
151	
152	.tile__beliefs > * + * {
153	  padding-left: var(--space-1);
154	  border-left: 1px solid var(--hairline);
155	}
156	
157	/* Why a slot has no number, in the map's own words. Two lines, then it stops —
158	 * the whole sentence is on the chip's shelf and, later, in the panel. */
159	.tile__absence {
160	  margin: 0;
161	  font-size: var(--text-sm);
162	  color: var(--text-muted);
163	  line-height: 1.35;
164	  text-wrap: pretty;
165	  display: -webkit-box;
166	  -webkit-box-orient: vertical;
167	  -webkit-line-clamp: 2;
168	  line-clamp: 2;
169	  overflow: hidden;
170	}
171	
172	/* The foot of the tile: why a slot has no number, the evidence clippings, and
173	 * the badges. Pushed to the bottom edge as one block, so that every tile in a
174	 * column has its claim on the same line and its clippings on the same line. */
175	.tile__foot {
176	  display: flex;
177	  flex-direction: column;
178	  gap: var(--space-1);
179	  margin-top: auto;
180	}
181	
182	/* ---- Evidence clippings ------------------------------------------------- *
183	 * A letter standing for the publication, a sign saying which way the item cuts,
184	 * and one line of what it says. The letter comes from the host name in the
185	 * source's own address rather than from the publication's icon: an icon is a
186	 * request to somebody else's server, and this app draws its first frame without
187	 * making one. */
188	
189	.tile__clippings {
190	  margin: 0;
191	  padding: 0;
192	  list-style: none;
193	  display: grid;
194	  row-gap: var(--space-hair);
195	  align-content: end;
196	}
197	
198	.tile__clipping {
199	  display: grid;
200	  grid-template-columns: auto auto minmax(0, 1fr);
201	  align-items: baseline;
202	  column-gap: var(--space-hair);
203	  font-size: var(--text-sm);
204	  color: var(--text-muted);
205	}
206	
207	.tile__monogram {
208	  display: inline-grid;
209	  place-items: center;
210	  width: var(--space-2);
211	  height: var(--space-2);
212	  border: 1px solid var(--hairline);
213	  border-radius: 2px;
214	  font-size: var(--text-sm);
215	  font-weight: var(--weight-medium);
216	  line-height: 1;
217	  color: var(--text-muted);
218	  align-self: center;
219	}
220	
221	.tile__clipping-sign {
222	  font-family: var(--font-mono);
223	  color: var(--text-muted);
224	}
225	
226	.tile__clipping-line {
227	  white-space: nowrap;
228	  overflow: hidden;
229	  text-overflow: ellipsis;
230	}
231	
232	/* Words that are read aloud but not drawn — the publication's name and which
233	 * way the item cuts, so the clipping reads as a sentence to a screen reader
234	 * while staying one line on screen. */
235	.tile__hidden {
236	  position: absolute;
237	  width: 1px;
238	  height: 1px;
239	  margin: -1px;
240	  padding: 0;
241	  overflow: hidden;
242	  clip-path: inset(50%);
243	  white-space: nowrap;
244	}
245	
246	/* ---- What an edit did to this claim ------------------------------------- *
247	 * Four states, each worked out from the branch and none of them from a number.
248	 * Every one of them is carried by something that survives being printed in grey
249	 * — a stroke, an opacity, a line through the words — and every one of them is
250	 * also said in words: in what the tile is called when it is read out loud, and
251	 * on the belief chip, which reads "no engine yet" wherever a likelihood would
252	 * have moved. */
253	
254	/* Added: the claim your edit brought. Its own outline goes solid and takes the
255	 * accent, so the newest thing on the map is the one thing drawn in a different
256	 * ink. */
257	.tile[data-diff="added"] .tile__outline path {
258	  stroke: var(--accent);
259	  stroke-width: 1.5;
260	}
261	
262	/* Supposed false: ghosted, desaturated, and the claim struck through. Three
263	 * cues, no colour among them. */
264	.tile[data-diff="killed"] {
265	  opacity: 0.45;
266	  filter: grayscale(1);
267	}
268	
269	.tile[data-diff="killed"] .tile__claim {
270	  text-decoration: line-through;
271	  text-decoration-thickness: 1px;
272	}
273	
274	/* A claim your edit can reach, and one it provably cannot: a strip along the
275	 * bottom edge, dashed for the first and absent for the second. The strip is the
276	 * glance; the chip's "no engine yet" is the reading. */
277	.tile[data-diff="downstream"]::after {
278	  content: "";
279	  position: absolute;
280	  left: var(--space-2);
281	  right: var(--space-2);
282	  bottom: 5px;
283	  height: 0;
284	  border-bottom: 1px dashed var(--accent);
285	}
286	
287	.tile[data-diff="added"]::after {
288	  content: "";
289	  position: absolute;
290	  left: var(--space-2);
291	  right: var(--space-2);
292	  bottom: 5px;
293	  height: 2px;
294	  background: var(--accent);
295	}
296	
297	/* A claim whose number moved: the same strip, drawn solid and thin. A claim
298	   your edit can reach is dashed, a claim whose number actually moved is joined
299	   up, and a claim it added is the thick one — three weights of one line, which
300	   survives a grey print. The reading itself is on the tile beside the badges,
301	   because the strip is a glance and never a number. */
302	.tile[data-diff="shifted"]::after {
303	  content: "";
304	  position: absolute;
305	  left: var(--space-2);
306	  right: var(--space-2);
307	  bottom: 5px;
308	  height: 0;
309	  border-bottom: 1px solid var(--accent);
310	}
311	
312	/* ---- Badges -------------------------------------------------------------- *
313	 * What the edits behind this claim did to it, in the order they were made:
314	 * *Supposed · Oct 1 → Retracted · Oct 2 · by "…"*. The arrow between two of them
315	 * is the whole point — the surprising rule reads as a sequence rather than as a
316	 * number that moved on its own.
317	 *
318	 * A badge is a button because each one carries a sentence saying what it means,
319	 * and a reason the keyboard cannot reach is not a reason. It looks nothing like
320	 * a button: a hairline, a hair of padding, no fill and no radius to speak of. */
321	
322	.tile__badges {
323	  display: block;
324	  margin: 0;
325	  font-size: var(--text-sm);
326	  line-height: 1.35;
327	  color: var(--text);
328	  text-wrap: pretty;
329	}
330	
331	.tile__badges:empty {
332	  display: none;
333	}
334	
335	.tile__badge-arrow {
336	  color: var(--text-muted);
337	}
338	
339	.tile__badge {
340	  display: inline;
341	  margin: 0;
342	  padding: 1px var(--space-hair);
343	  border: 1px solid var(--hairline);
344	  border-radius: 2px;
345	  background: var(--surface);
346	  font-family: inherit;
347	  font-size: var(--text-sm);
348	  font-weight: var(--weight-medium);
349	  line-height: 1.35;
350	  color: var(--text);
351	  text-align: left;
352	  cursor: help;
353	}
354	
355	.tile__badge:hover {
356	  border-color: var(--text-muted);
357	}
358	
359	/* A badge that is a reading rather than a word about an edit: the two numbers
360	   with a chevron between them. It takes the number face and the tabular digits
361	   every number in this product is set in, so that `.40 ▼ .30` reads as two
362	   numbers and not as a label. It takes no colour of its own: which way a
363	   likelihood went is said by the two numbers and by the chevron, and the two
364	   hues this product keeps for a direction mean which way the money moves, which
365	   is a different thing. */
366	
367	.tile__badge[data-badge="movement"] .tile__badge-words {
368	  font-family: var(--font-mono);
369	  font-variant-numeric: tabular-nums;
370	  letter-spacing: 0.01em;
371	}
372	
373	/* The reading gets a line of its own under whatever the edits had to say. On
374	   the busiest tile the badge run is already three lines, and a fourth thing
375	   strung on the end of it pushes a line out of the box — so it starts a line,
376	   and the layout reserves one for it. */
377	.tile__badges--movement {
378	  margin-top: var(--space-hair);
379	}
380	
381	/* ---- The collapsed tile ------------------------------------------------- *
382	 * Same size and same hairline as a claim's tile, but drawn with a dashed line,
383	 * because it is not a claim — it is the count of the ones a column had no room
384	 * for. */
385	
386	.tile--overflow {
387	  justify-content: center;
388	  text-align: center;
389	}
390	
391	.tile--overflow .tile__outline rect {
392	  fill: none;
393	  stroke: var(--hairline);
394	  stroke-width: 1;
395	}
396	
397	.tile__overflow-count {
398	  margin: 0;
399	  font-family: var(--font-mono);
400	  font-variant-numeric: tabular-nums;
401	  font-size: var(--text-lg);
402	  font-weight: var(--weight-medium);
403	  color: var(--text);
404	}
405	
406	.tile__overflow-line {
407	  margin: 0;
408	  font-size: var(--text-sm);
409	  color: var(--text-muted);
410	  text-wrap: pretty;
411	}
412	
413	/* ---- Far out: the summary ---------------------------------------------- *
414	 * Zoomed out past the threshold a tile changes what it draws rather than
415	 * shrinking what it draws. It keeps the claim and the three readings and drops
416	 * everything else — the kind, the date, the reason a slot is empty, the
417	 * clippings — and it sets every word it keeps in the largest of the three type
418	 * sizes. That last part is what makes the eleven-pixel floor true: twenty-two
419	 * pixels at the furthest the map zooms out, which is half, is eleven pixels on
420	 * the reader's screen, and the map does not zoom out past half.
421	 *
422	 * The three readings stop being a three-up row out here and become three lines,
423	 * each one read the way it would be said: the owner, the number, the range. A
424	 * range is never dropped, at any zoom. */
425	
426	.tile[data-detail="summary"] {
427	  gap: var(--space-2);
428	  justify-content: center;
429	}
430	
431	.tile[data-detail="summary"] .tile__header,
432	.tile[data-detail="summary"] .tile__foot {
433	  display: none;
434	}
435	
436	.tile[data-detail="summary"] .tile__claim {
437	  font-size: var(--text-lg);
438	  line-height: 1.25;
439	  font-weight: var(--weight-medium);
440	  /* Two lines out here whatever the full tile shows: the summary is a glance,
441	   * not a read. */
442	  -webkit-line-clamp: 2;
443	  line-clamp: 2;
444	}
445	
446	.tile[data-detail="summary"] .tile__beliefs {
447	  /* One line per owner, stacked. The row above makes its columns from the
448	   * chips themselves, so out here the flow has to be turned back to rows as
449	   * well — otherwise a second chip takes a column of its own beside the first
450	   * and the two lines are printed over each other (Kent saw exactly that on the
451	   * one tile holding a venue's number, 2026-09-22). */
452	  grid-auto-flow: row;
453	  grid-template-columns: minmax(0, 1fr);
454	  row-gap: var(--space-hair);
455	}
456	
457	.tile[data-detail="summary"] .tile__beliefs > * + * {
458	  padding-left: 0;
459	  border-left: none;
460	}
461	
462	.tile[data-detail="summary"] .belief-chip__face {
463	  /* The owner's column is measured in this line's own type size, so the line
464	   * has to be set at that size before the column is worked out. */
465	  font-size: var(--text-lg);
466	  grid-template-rows: auto;
467	  /* The owner's column is as wide as the longest owner, *market*, and no wider.
468	   * It was a fifth wider than that, and the line then ran past the row by 5
469	   * pixels on an ordinary tile and by 17 on the two whose outline cuts into one
470	   * side — far enough that the end of the range was cut off (measured on the
471	   * stored example at the furthest zoom, 2026-09-22). */
472	  grid-template-columns: 3.5em auto auto;
473	  grid-auto-flow: column;
474	  justify-items: start;
475	  align-items: baseline;
476	  column-gap: var(--space-1);
477	  width: 100%;
478	}
479	
480	.tile[data-detail="summary"] .belief-chip__owner,
481	.tile[data-detail="summary"] .belief-chip__reading,
482	.tile[data-detail="summary"] .belief-chip__under {
483	  font-size: var(--text-lg);
484	  line-height: 1.25;
485	  min-height: 0;
486	}
487	
488	/* ---- The ports ---------------------------------------------------------- *
489	 * One group of inputs on the left, one group of outputs on the right, and two
490	 * sockets in each: an arrow that fires once and stays fired lands in a
491	 * different socket from one that has to keep holding. A single tick for the
492	 * first, a double tick for the second — the same doubling the wire itself will
493	 * use, so the socket and the wire say the same thing.
494	 *
495	 * **Where a port sits is not here.** Its box — left, top, width and height —
496	 * depends on how tall its tile turned out to be, and the drawing library is
497	 * handed those same four numbers so that it can draw a wire before it has
498	 * measured anything. So `graph/ports.ts` works them out and `Tile.tsx` writes
499	 * them onto the element; a second copy in a stylesheet is a second thing to
500	 * keep in step, and it would not be kept. What is left below is only how a port
501	 * looks — which is an override of the drawing library's own handle styling, a
502	 * blue circle, because nothing in this product looks like the library it was
503	 * built with.
504	 *
505	 * Each bar below is measured in pixels down from the top of the port, and the
506	 * last stop of each run is written `100%` — the foot of the port, whatever the
507	 * port's height turns out to be. Writing that height here as a number would be
508	 * the second copy this section exists to do without. */
509	
510	.tile__port.react-flow__handle {
511	  min-width: 0;
512	  min-height: 0;
513	  border: none;
514	  border-radius: 0;
515	  background: none;
516	}
517	
518	/* One bar: fires once, and stays fired. Shifted down by its own thickness, and
519	 * repeating, so the single bar lands in the middle of the port. */
520	.tile__port--trigger {
521	  background: linear-gradient(var(--text-muted) 0 2px, transparent 2px 100%);
522	  background-position: 0 2px;
523	}
524	
525	/* Two bars: holds only while its cause holds. */
526	.tile__port--sustain {
527	  background: linear-gradient(
528	    var(--text-muted) 0 2px,
529	    transparent 2px 4px,
530	    var(--text-muted) 4px 100%
531	  );
532	}
