/*
 * The tile.
 *
 * Two rules run through all of it. First, everything sits on the eight-pixel
 * grid and takes its colour, its type and its spacing from `tokens.css`; there
 * are two raw numbers below and both are commented where they appear. Second,
 * there are no shadows anywhere — separation comes from a one-pixel line at a
 * tenth of the text colour, which is drawn as part of the tile's outline rather
 * than as a border, so that a hypothesis and a dead end can be different shapes.
 */

.tile {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  /* Twelve pixels of internal padding, settled. It is one and a half steps of
   * the eight-pixel grid: the grid governs where things sit relative to each
   * other, and twelve is the distance from the drawn outline to the first word,
   * which wants to be tighter than sixteen and looser than eight. */
  padding: 12px;
  font-family: var(--font-interface);
  color: var(--text);
  /* No background of its own: the drawn outline below fills the shape, so the
   * fill follows the shape exactly rather than squaring off its corners. */
  background: none;
  /* The tile's own words may leave its box — the shelf a belief chip opens
   * hangs below it — so nothing here clips. */
  overflow: visible;
  /* The tile stacks its own parts among themselves and not among its
   * neighbours' parts. Without this the drawn outline below, which has to sit
   * behind the words, would sink behind the map itself and take the tile's fill
   * with it. */
  isolation: isolate;
}

/* Nothing inside a tile is ever squeezed. The tile's height was worked out from
 * exactly these blocks, so if the arithmetic is a fraction of a pixel out the
 * right answer is for the tile to be a fraction of a pixel taller — not for the
 * claim to lose the bottom of its last line, which is what a flexible box does
 * by default and which reads as text cut in half. */
.tile__header,
.tile__claim,
.tile__beliefs,
.tile__foot {
  flex: none;
}

/* The drawn outline: the fill and the one-pixel line, in the shape that says
 * what kind of claim this is. Sits behind everything in the tile, and takes no
 * clicks. */
.tile__outline {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
}

.tile__outline path {
  fill: var(--surface-raised);
  stroke: var(--hairline);
  stroke-width: 1;
}

/* Two of the four outlines cut into the tile on one side — the hypothesis comes
 * to a point on the left, the dead end is notched on the right — so those two
 * tiles hold their words a step further from that edge. Nothing is ever drawn
 * across a word. */
.tile[data-kind="hypothesis"] {
  padding-left: var(--space-3);
}

.tile[data-kind="not_tradeable"] {
  padding-right: var(--space-3);
}

/* The claim the reader started from is the one thing on the map that did not
 * come from the model, so its outline is drawn in the accent rather than in the
 * hairline. The shape already says it is the hypothesis; this only makes the
 * eye land there first. */
.tile[data-hypothesis="yes"] .tile__outline path {
  stroke: var(--accent);
}

/* ---- The header: what kind of claim, and when it settles ---------------- */

.tile__header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--space-1);
  font-size: var(--text-sm);
  color: var(--text-muted);
  min-width: 0;
}

.tile__kind {
  font-weight: var(--weight-medium);
  letter-spacing: 0.04em;
  white-space: nowrap;
}

.tile__resolves {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

/* ---- The claim ---------------------------------------------------------- *
 * As many lines as the tile was built to hold — at most three — and then it
 * stops. The number comes from the same place the tile's height came from, so
 * the claim stops exactly where the box ends and never a line later. The stop
 * is by line rather than by character, so a word is never cut in half to save a
 * few pixels; the rest of the sentence lives in the panel beside the map. */

.tile__claim {
  margin: 0;
  font-size: var(--text-md);
  line-height: 1.35;
  color: var(--text);
  text-wrap: pretty;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: var(--tile-claim-lines, 3);
  line-clamp: var(--tile-claim-lines, 3);
  overflow: hidden;
}

/* ---- The beliefs -------------------------------------------------------- *
 * Side by side, equal widths, with a hairline between them. One column per
 * owner who has something to say: the model always, and the reader and a venue
 * where they hold a number. They are never merged into one number — the shape
 * of the row is the argument — and a column with nothing in it is not drawn.
 *
 * The columns are made by the chips rather than declared as three, so the row
 * shares its whole width between whichever of them are there: one chip fills
 * the tile, two take half each, three take a third each exactly as before.
 * **The tile does not change size either way.** Its height and its width are
 * written on its own box from `geometry.ts`, which reserves the same rail
 * whatever the chips hold — so a number arriving later widens the survivors and
 * re-lays out nothing. */

.tile__beliefs {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(0, 1fr);
  column-gap: var(--space-1);
  padding-top: var(--space-1);
  border-top: 1px solid var(--hairline);
}

.tile__beliefs > * + * {
  padding-left: var(--space-1);
  border-left: 1px solid var(--hairline);
}

/* Why a slot has no number, in the map's own words. Two lines, then it stops —
 * the whole sentence is on the chip's shelf and, later, in the panel. */
.tile__absence {
  margin: 0;
  font-size: var(--text-sm);
  color: var(--text-muted);
  line-height: 1.35;
  text-wrap: pretty;
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
}

/* The foot of the tile: why a slot has no number, the evidence clippings, and
 * the badges. Pushed to the bottom edge as one block, so that every tile in a
 * column has its claim on the same line and its clippings on the same line. */
.tile__foot {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
  margin-top: auto;
}

/* ---- Evidence clippings ------------------------------------------------- *
 * A letter standing for the publication, a sign saying which way the item cuts,
 * and one line of what it says. The letter comes from the host name in the
 * source's own address rather than from the publication's icon: an icon is a
 * request to somebody else's server, and this app draws its first frame without
 * making one. */

.tile__clippings {
  margin: 0;
  padding: 0;
  list-style: none;
  display: grid;
  row-gap: var(--space-hair);
  align-content: end;
}

.tile__clipping {
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr);
  align-items: baseline;
  column-gap: var(--space-hair);
  font-size: var(--text-sm);
  color: var(--text-muted);
}

.tile__monogram {
  display: inline-grid;
  place-items: center;
  width: var(--space-2);
  height: var(--space-2);
  border: 1px solid var(--hairline);
  border-radius: 2px;
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  line-height: 1;
  color: var(--text-muted);
  align-self: center;
}

.tile__clipping-sign {
  font-family: var(--font-mono);
  color: var(--text-muted);
}

.tile__clipping-line {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Words that are read aloud but not drawn — the publication's name and which
 * way the item cuts, so the clipping reads as a sentence to a screen reader
 * while staying one line on screen. */
.tile__hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* ---- What an edit did to this claim ------------------------------------- *
 * Four states, each worked out from the branch and none of them from a number.
 * Every one of them is carried by something that survives being printed in grey
 * — a stroke, an opacity, a line through the words — and every one of them is
 * also said in words: in what the tile is called when it is read out loud, and
 * on the belief chip, which reads "no engine yet" wherever a likelihood would
 * have moved. */

/* Added: the claim your edit brought. Its own outline goes solid and takes the
 * accent, so the newest thing on the map is the one thing drawn in a different
 * ink. */
.tile[data-diff="added"] .tile__outline path {
  stroke: var(--accent);
  stroke-width: 1.5;
}

/* Supposed false: ghosted, desaturated, and the claim struck through. Three
 * cues, no colour among them. */
.tile[data-diff="killed"] {
  opacity: 0.45;
  filter: grayscale(1);
}

.tile[data-diff="killed"] .tile__claim {
  text-decoration: line-through;
  text-decoration-thickness: 1px;
}

/* A claim your edit can reach, and one it provably cannot: a strip along the
 * bottom edge, dashed for the first and absent for the second. The strip is the
 * glance; the chip's "no engine yet" is the reading. */
.tile[data-diff="downstream"]::after {
  content: "";
  position: absolute;
  left: var(--space-2);
  right: var(--space-2);
  bottom: 5px;
  height: 0;
  border-bottom: 1px dashed var(--accent);
}

.tile[data-diff="added"]::after {
  content: "";
  position: absolute;
  left: var(--space-2);
  right: var(--space-2);
  bottom: 5px;
  height: 2px;
  background: var(--accent);
}

/* A claim whose number moved: the same strip, drawn solid and thin. A claim
   your edit can reach is dashed, a claim whose number actually moved is joined
   up, and a claim it added is the thick one — three weights of one line, which
   survives a grey print. The reading itself is on the tile beside the badges,
   because the strip is a glance and never a number. */
.tile[data-diff="shifted"]::after {
  content: "";
  position: absolute;
  left: var(--space-2);
  right: var(--space-2);
  bottom: 5px;
  height: 0;
  border-bottom: 1px solid var(--accent);
}

/* ---- Badges -------------------------------------------------------------- *
 * What the edits behind this claim did to it, in the order they were made:
 * *Supposed · Oct 1 → Retracted · Oct 2 · by "…"*. The arrow between two of them
 * is the whole point — the surprising rule reads as a sequence rather than as a
 * number that moved on its own.
 *
 * A badge is a button because each one carries a sentence saying what it means,
 * and a reason the keyboard cannot reach is not a reason. It looks nothing like
 * a button: a hairline, a hair of padding, no fill and no radius to speak of. */

.tile__badges {
  display: block;
  margin: 0;
  font-size: var(--text-sm);
  line-height: 1.35;
  color: var(--text);
  text-wrap: pretty;
}

.tile__badges:empty {
  display: none;
}

.tile__badge-arrow {
  color: var(--text-muted);
}

.tile__badge {
  display: inline;
  margin: 0;
  padding: 1px var(--space-hair);
  border: 1px solid var(--hairline);
  border-radius: 2px;
  background: var(--surface);
  font-family: inherit;
  font-size: var(--text-sm);
  font-weight: var(--weight-medium);
  line-height: 1.35;
  color: var(--text);
  text-align: left;
  cursor: help;
}

.tile__badge:hover {
  border-color: var(--text-muted);
}

/* A badge that is a reading rather than a word about an edit: the two numbers
   with a chevron between them. It takes the number face and the tabular digits
   every number in this product is set in, so that `.40 ▼ .30` reads as two
   numbers and not as a label. It takes no colour of its own: which way a
   likelihood went is said by the two numbers and by the chevron, and the two
   hues this product keeps for a direction mean which way the money moves, which
   is a different thing. */

.tile__badge[data-badge="movement"] .tile__badge-words {
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.01em;
}

/* The reading gets a line of its own under whatever the edits had to say. On
   the busiest tile the badge run is already three lines, and a fourth thing
   strung on the end of it pushes a line out of the box — so it starts a line,
   and the layout reserves one for it. */
.tile__badges--movement {
  margin-top: var(--space-hair);
}

/* ---- The collapsed tile ------------------------------------------------- *
 * Same size and same hairline as a claim's tile, but drawn with a dashed line,
 * because it is not a claim — it is the count of the ones a column had no room
 * for. */

.tile--overflow {
  justify-content: center;
  text-align: center;
}

.tile--overflow .tile__outline rect {
  fill: none;
  stroke: var(--hairline);
  stroke-width: 1;
}

.tile__overflow-count {
  margin: 0;
  font-family: var(--font-mono);
  font-variant-numeric: tabular-nums;
  font-size: var(--text-lg);
  font-weight: var(--weight-medium);
  color: var(--text);
}

.tile__overflow-line {
  margin: 0;
  font-size: var(--text-sm);
  color: var(--text-muted);
  text-wrap: pretty;
}

/* ---- Far out: the summary ---------------------------------------------- *
 * Zoomed out past the threshold a tile changes what it draws rather than
 * shrinking what it draws. It keeps the claim and the three readings and drops
 * everything else — the kind, the date, the reason a slot is empty, the
 * clippings — and it sets every word it keeps in the largest of the three type
 * sizes. That last part is what makes the eleven-pixel floor true: twenty-two
 * pixels at the furthest the map zooms out, which is half, is eleven pixels on
 * the reader's screen, and the map does not zoom out past half.
 *
 * The three readings stop being a three-up row out here and become three lines,
 * each one read the way it would be said: the owner, the number, the range. A
 * range is never dropped, at any zoom. */

.tile[data-detail="summary"] {
  gap: var(--space-2);
  justify-content: center;
}

.tile[data-detail="summary"] .tile__header,
.tile[data-detail="summary"] .tile__foot {
  display: none;
}

.tile[data-detail="summary"] .tile__claim {
  font-size: var(--text-lg);
  line-height: 1.25;
  font-weight: var(--weight-medium);
  /* Two lines out here whatever the full tile shows: the summary is a glance,
   * not a read. */
  -webkit-line-clamp: 2;
  line-clamp: 2;
}

.tile[data-detail="summary"] .tile__beliefs {
  /* One line per owner, stacked. The row above makes its columns from the
   * chips themselves, so out here the flow has to be turned back to rows as
   * well — otherwise a second chip takes a column of its own beside the first
   * and the two lines are printed over each other (Kent saw exactly that on the
   * one tile holding a venue's number, 2026-09-22). */
  grid-auto-flow: row;
  grid-template-columns: minmax(0, 1fr);
  row-gap: var(--space-hair);
}

.tile[data-detail="summary"] .tile__beliefs > * + * {
  padding-left: 0;
  border-left: none;
}

.tile[data-detail="summary"] .belief-chip__face {
  /* The owner's column is measured in this line's own type size, so the line
   * has to be set at that size before the column is worked out. */
  font-size: var(--text-lg);
  grid-template-rows: auto;
  /* The owner's column is as wide as the longest owner, *market*, and no wider.
   * It was a fifth wider than that, and the line then ran past the row by 5
   * pixels on an ordinary tile and by 17 on the two whose outline cuts into one
   * side — far enough that the end of the range was cut off (measured on the
   * stored example at the furthest zoom, 2026-09-22). */
  grid-template-columns: 3.5em auto auto;
  grid-auto-flow: column;
  justify-items: start;
  align-items: baseline;
  column-gap: var(--space-1);
  width: 100%;
}

.tile[data-detail="summary"] .belief-chip__owner,
.tile[data-detail="summary"] .belief-chip__reading,
.tile[data-detail="summary"] .belief-chip__under {
  font-size: var(--text-lg);
  line-height: 1.25;
  min-height: 0;
}

/* ---- The ports ---------------------------------------------------------- *
 * One group of inputs on the left, one group of outputs on the right, and two
 * sockets in each: an arrow that fires once and stays fired lands in a
 * different socket from one that has to keep holding. A single tick for the
 * first, a double tick for the second — the same doubling the wire itself will
 * use, so the socket and the wire say the same thing.
 *
 * **Where a port sits is not here.** Its box — left, top, width and height —
 * depends on how tall its tile turned out to be, and the drawing library is
 * handed those same four numbers so that it can draw a wire before it has
 * measured anything. So `graph/ports.ts` works them out and `Tile.tsx` writes
 * them onto the element; a second copy in a stylesheet is a second thing to
 * keep in step, and it would not be kept. What is left below is only how a port
 * looks — which is an override of the drawing library's own handle styling, a
 * blue circle, because nothing in this product looks like the library it was
 * built with.
 *
 * Each bar below is measured in pixels down from the top of the port, and the
 * last stop of each run is written `100%` — the foot of the port, whatever the
 * port's height turns out to be. Writing that height here as a number would be
 * the second copy this section exists to do without. */

.tile__port.react-flow__handle {
  min-width: 0;
  min-height: 0;
  border: none;
  border-radius: 0;
  background: none;
}

/* One bar: fires once, and stays fired. Shifted down by its own thickness, and
 * repeating, so the single bar lands in the middle of the port. */
.tile__port--trigger {
  background: linear-gradient(var(--text-muted) 0 2px, transparent 2px 100%);
  background-position: 0 2px;
}

/* Two bars: holds only while its cause holds. */
.tile__port--sustain {
  background: linear-gradient(
    var(--text-muted) 0 2px,
    transparent 2px 4px,
    var(--text-muted) 4px 100%
  );
}

/**
 * A claim, as a card on the map.
 *
 * A tile shows six things and no more, because a seventh always arrives at the
 * cost of the six:
 *
 *   1. the claim, wrapping to three lines and then stopping — never cut in the
 *      middle of a word;
 *   2. the belief chips, side by side and never averaged: the model's always,
 *      and the reader's and a market's where they hold a number. A column with
 *      nothing in it is two thirds of the belief area on a generated map, so
 *      it is not drawn — the absence and its own reason are read in full in the
 *      panel beside the map, which is where a reason has room to be a sentence;
 *   3. at most two evidence clippings, each a letter standing for a publication
 *      and one line of what it says;
 *   4. the day the claim is settled by;
 *   5. its outline, which says what kind of claim it is — shape carries that,
 *      never colour;
 *   6. a place for its badges, which arrive with the buttons that earn them.
 *
 * The rest — the full claim, the resolution criteria, the sources, the
 * reasoning behind a number — belongs in the panel beside the map, which is
 * built in the pull request after this one.
 *
 * **The outline is drawn rather than bordered.** The tile has no border of its
 * own; a line drawing sits behind it with a one-pixel stroke at a tenth of the
 * text colour, and its path is what makes a hypothesis look different from a
 * dead end. Four shapes, four kinds, and the shapes survive being printed in
 * grey — which a colour never does.
 */

import { Handle, useStore } from "@xyflow/react";
import { toDay } from "../graph/diff/days";
import { claimLines, SUMMARY_BELOW_ZOOM, TILE_WIDTH, tileHeight } from "../graph/geometry";
import { PORTS, portBox } from "../graph/ports";
import type { Badge, ClaimKind, ClaimView } from "../world";
import { BeliefChip } from "./BeliefChip";
import "./tile.css";

/**
 * The four outlines, as line drawings the width and height of a tile.
 *
 * Each one is drawn to the height its own tile turned out to be, because a tile
 * is as tall as its content. Every path is offset by half a pixel so that a
 * one-pixel stroke lands on a pixel boundary instead of straddling two and
 * going soft.
 *
 * - **hypothesis** — the left edge comes to a point. This is where the map
 *   starts: the claim the reader typed, with nothing before it.
 * - **event** — an ordinary rounded box. A step in the middle of the chain.
 * - **market** — the top right corner is cut away, the way a ticket is. There
 *   is something here you could actually trade.
 * - **not tradeable** — the right edge is notched inward. The chain really does
 *   end here, and there is nothing to plug into it.
 *
 * Two of the four cut into the space a word would sit in, so those two tiles are
 * given a wider margin on that side — see `tile.css`. A shape that crosses its
 * own words is not a shape, it is a mistake.
 */
const OUTLINES: Record<ClaimKind, (height: number) => string> = {
  hypothesis: (h) => `M 16.5 0.5 H ${TILE_WIDTH - 0.5} V ${h - 0.5} H 16.5 L 0.5 ${h / 2} Z`,
  event: (h) =>
    `M 6.5 0.5 H ${TILE_WIDTH - 6.5} A 6 6 0 0 1 ${TILE_WIDTH - 0.5} 6.5 V ${h - 6.5} ` +
    `A 6 6 0 0 1 ${TILE_WIDTH - 6.5} ${h - 0.5} H 6.5 A 6 6 0 0 1 0.5 ${h - 6.5} ` +
    `V 6.5 A 6 6 0 0 1 6.5 0.5 Z`,
  market: (h) => `M 0.5 0.5 H ${TILE_WIDTH - 18.5} L ${TILE_WIDTH - 0.5} 18.5 V ${h - 0.5} H 0.5 Z`,
  not_tradeable: (h) =>
    `M 0.5 0.5 H ${TILE_WIDTH - 0.5} V ${h / 2 - 14} L ${TILE_WIDTH - 14.5} ${h / 2} ` +
    `L ${TILE_WIDTH - 0.5} ${h / 2 + 14} V ${h - 0.5} H 0.5 Z`,
};

/** What each kind is called on screen. No underscores and no code names. */
const KIND_WORDS: Record<ClaimKind, string> = {
  hypothesis: "hypothesis",
  event: "event",
  market: "market",
  not_tradeable: "not tradeable",
};

/**
 * What an edit did to this claim, in the words a reader hears rather than the
 * word the code uses. Read out before the claim itself, so a reader who never
 * sees the tile learns the same thing first.
 */
const DIFF_WORDS: Record<string, string> = {
  added: "added by your edit",
  killed: "supposed false by your edit",
  downstream: "your edit can reach this",
  untouched: "your edit cannot reach this",
  shifted: "your edit moved this number",
};

/** One published item, as a clipping: a letter for the publication and one line. */
function Clipping({
  monogram,
  host,
  line,
  direction,
}: {
  monogram: string;
  host: string;
  line: string;
  direction: 1 | -1;
}) {
  // A sign, not a colour: "+" for an item that supports the claim, "−" for one
  // that cuts against it. A reader who cannot tell two hues apart loses nothing.
  const sign = direction === 1 ? "+" : "−";
  const inWords = direction === 1 ? "supports this claim" : "cuts against this claim";
  return (
    <li className="tile__clipping">
      <span className="tile__monogram" aria-hidden="true">
        {monogram}
      </span>
      <span className="tile__clipping-sign" aria-hidden="true">
        {sign}
      </span>
      <span className="tile__clipping-line">
        <span className="tile__hidden">{`${host}, ${inWords}: `}</span>
        {line}
      </span>
    </li>
  );
}

/**
 * What a claim's tile says about the edits behind it, in the order they were
 * made.
 *
 * Two badges in a row are drawn as a sequence with an arrow between them, which
 * is the whole point of UX-14: *Supposed · Oct 1 → Retracted · Oct 2 · by "a
 * confirmed military strike on Iranian territory"*. Met as a sequence the rule
 * that a later edit outranks an earlier supposition is obvious; met as a number
 * that moved on its own it reads as a bug.
 *
 * Every badge is also a thing the keyboard can land on, because each one carries
 * a sentence saying what it means, and a reason you cannot reach is not a reason.
 */
function Badges({ badges }: { badges: readonly Badge[] }) {
  // How far the number moved is a reading, not a word about an edit, so it gets
  // a line of its own under the run rather than being strung on the end of it.
  // Two reasons, and the second is the load-bearing one: *Supposed · Oct 1 →
  // Retracted · Oct 2 · by "…"* already runs to three lines on a 280-pixel tile,
  // and a fourth thing on that run pushes a line out of the box. The layout
  // reserves the extra line; see `App.tsx`, where the box is measured.
  const said = badges.filter((badge) => badge.movement !== true);
  const moved = badges.find((badge) => badge.movement === true);
  if (said.length === 0 && moved === undefined) {
    return null;
  }
  return (
    <>
      {said.length === 0 ? null : (
        <p className="tile__badges">
          {said.map((badge, index) => (
            <span className="tile__badge-run" key={badge.words}>
              {index === 0 ? null : (
                <span className="tile__badge-arrow" aria-hidden="true">
                  {" → "}
                </span>
              )}
              <button className="tile__badge" type="button" title={badge.reason} data-badge="words">
                <span className="tile__hidden">{`${badge.reason} `}</span>
                <span className="tile__badge-words">{badge.words}</span>
              </button>
            </span>
          ))}
        </p>
      )}
      {moved === undefined ? null : (
        // Drawn in the number face, so that `.40 ▼ .30` reads as two numbers
        // with a direction between them rather than as a label.
        <p className="tile__badges tile__badges--movement">
          <button className="tile__badge" type="button" title={moved.reason} data-badge="movement">
            <span className="tile__hidden">{`${moved.reason} `}</span>
            <span className="tile__badge-words">{moved.words}</span>
          </button>
        </p>
      )}
    </>
  );
}

/** What a tile needs to draw itself. */
export interface TileProps {
  /** The claim this tile is for. */
  readonly claim: ClaimView;
  /** True when this claim is the one the reader started from. */
  readonly isHypothesis: boolean;
  /**
   * How many versions of the map were run to produce this world's numbers.
   *
   * Absent means nothing computed them, and the model chip says so instead of
   * describing a run that never happened.
   */
  readonly versions?: number;
  /**
   * The height the map reserved for this tile.
   *
   * Usually the same as the tile's own content needs. It differs only in a
   * diff, where one box has to hold whichever of the two paintings is taller, so
   * that flipping between them moves nothing.
   */
  readonly height?: number;
}

/** One claim's tile. */
export function Tile({ claim, isHypothesis, versions, height: reserved }: TileProps) {
  // How far the map is zoomed out. Below the threshold a tile stops showing
  // everything and shows a summary instead — the claim and the three chips —
  // because the alternative is type too small to read. The tile changes what it
  // draws; it never shrinks what it draws.
  const zoom = useStore((state) => state.transform[2]);
  const detail = zoom < SUMMARY_BELOW_ZOOM ? "summary" : "full";

  // Only one claim in four prints why it has no market: the kind that ends the
  // map without an instrument. That reason is a finding — somebody looked and
  // wrote down what they found — and it belongs on the face of the tile. For
  // every other claim "no market" is a fact about the world's plumbing, the
  // chip says it in two words, and the sentence behind it is on the chip's
  // shelf and in what the chip is called when it is read out loud.
  const finding = claim.kind === "not_tradeable" ? claim.beliefs.market.absence : undefined;
  // As tall as this claim's own content, worked out the same way the layout
  // worked it out, so the box the map reserved and the box the browser draws
  // are the same box.
  const height = reserved ?? tileHeight(claim);
  const lines = claimLines(claim.claim);
  // The foot only exists when it has something in it. An empty one would still
  // take a gap above it, and the tile would have a step of dead space at the
  // bottom — which is the whole thing a clamped height is meant to avoid. When
  // the badges arrive, having one of those puts the foot there too.
  const badges = claim.badges ?? [];
  const hasFoot = finding !== undefined || claim.evidence.length > 0 || badges.length > 0;
  // What an edit did to this claim, said in words before the claim itself for a
  // reader who never sees the tile. Absent on a map nobody has edited.
  const diffWords = claim.diff === undefined ? "" : `${DIFF_WORDS[claim.diff] ?? claim.diff}. `;

  return (
    <article
      className="tile"
      data-kind={claim.kind}
      data-detail={detail}
      data-hypothesis={isHypothesis ? "yes" : "no"}
      data-diff={claim.diff ?? "none"}
      style={{
        width: `${TILE_WIDTH}px`,
        height: `${height}px`,
        // How many lines of the claim to show. The same number the height was
        // worked out from, so the claim stops exactly where the box ends.
        ["--tile-claim-lines" as string]: `${lines}`,
      }}
      aria-label={`${diffWords}${KIND_WORDS[claim.kind]}: ${claim.claim}`}
    >
      <svg
        className="tile__outline"
        width={TILE_WIDTH}
        height={height}
        viewBox={`0 0 ${TILE_WIDTH} ${height}`}
        aria-hidden="true"
        focusable="false"
      >
        <path d={OUTLINES[claim.kind](height)} />
      </svg>

      {/* The ports. An arrow that fires once and an arrow that has to keep
          holding are different claims about the world, so they arrive at
          different sockets and leave from different sockets — what a wire means
          is visible where it lands, before you follow it anywhere.

          **Each one's box is written on it rather than left to a stylesheet**,
          because where a port sits depends on how tall this tile turned out to
          be, and because the drawing library is handed these very numbers so
          that it can draw a wire before it has measured anything. `ports.ts`
          works them out; this writes them down; nothing measures them. */}
      {PORTS.map((port) => {
        const box = portBox(height, port);
        return (
          <Handle
            key={port.id}
            type={port.kind}
            position={port.edge}
            id={port.id}
            className={`tile__port tile__port--${port.mode}`}
            style={{
              left: `${box.x}px`,
              // The library's own stylesheet pins a port to the edge it is on
              // and then shifts it by half its own size. Both are said here
              // instead, in full, so that the box on the screen is the box that
              // was declared and there is nothing left to work out.
              right: "auto",
              top: `${box.y}px`,
              width: `${box.width}px`,
              height: `${box.height}px`,
              transform: "none",
            }}
          />
        );
      })}

      <header className="tile__header">
        <span className="tile__kind">{KIND_WORDS[claim.kind]}</span>
        <time className="tile__resolves" dateTime={claim.resolvesBy}>
          {`resolves ${toDay(claim.resolvesBy)}`}
        </time>
      </header>

      <p className="tile__claim">{claim.claim}</p>

      <div className="tile__beliefs">
        {/* The model's column is always drawn — it is the one number every
            claim on every map has, and while a map is still being built it is
            the column that says so. The reader's and a venue's are drawn only
            where they hold a number; where they do not, the absence and its
            reason are read in full in the panel beside the map. */}
        <BeliefChip
          owner="model"
          slot={claim.beliefs.model}
          standing={claim.standing}
          versions={versions}
        />
        {claim.beliefs.user.reading === undefined ? null : (
          <BeliefChip owner="user" slot={claim.beliefs.user} />
        )}
        {claim.beliefs.market.reading === undefined ? null : (
          <BeliefChip owner="market" slot={claim.beliefs.market} />
        )}
      </div>

      {detail === "full" && hasFoot ? (
        // The foot of the tile. It is pushed to the bottom edge as one block, so
        // that on every tile alike the claim is at the top, the beliefs are in
        // the middle and whatever is left sits on the floor — and the eye can
        // read down a column without hunting for the line it wants.
        <div className="tile__foot">
          {finding === undefined ? null : <p className="tile__absence">{finding.reason}</p>}

          {claim.evidence.length === 0 ? null : (
            <ul className="tile__clippings">
              {claim.evidence.map((item) => (
                <Clipping
                  key={item.line}
                  monogram={item.monogram}
                  host={item.host}
                  line={item.line}
                  direction={item.direction}
                />
              ))}
            </ul>
          )}

          {/* What the edits behind this claim did to it, in order. Empty on a
              map nobody has edited, and then it takes no room at all. */}
          <Badges badges={badges} />
        </div>
      ) : null}
    </article>
  );
}

