1	/**
2	 * There is no spinner anywhere in this product, and there never will be.
3	 *
4	 * A spinner says only "wait". The thing being waited for has a shape — a claim at
5	 * a column, a number in a slot — and the shape says "wait" *and* what for *and*
6	 * where it will land. It is also a named veto condition: a spinner followed by a
7	 * dump is one of the two things that end a line of work on sight.
8	 *
9	 * So this walks every stylesheet and every component in the tree and holds three
10	 * lines.
11	 *
12	 * 1. **Nothing spins, pulses or sweeps.** Every animation in the product changes
13	 *    opacity and nothing else. Nothing rotates, scales, moves, grows, or slides a
14	 *    gradient across itself, and nothing loops.
15	 * 2. **Nothing is an indeterminate progress indicator.** No element is given the
16	 *    part a screen reader reads as "progress" without a value to read.
17	 * 3. **Nothing calls itself a spinner, or a loader, or loading.** A word is a
18	 *    good proxy for an intention, and the intention is what this test is about.
19	 *
20	 * It is the same technique the colour law uses: read the files as text and walk
21	 * them, so that a rule added in a stylesheet nobody thought about is still found.
22	 */
23	
24	import { readdirSync, readFileSync, statSync } from "node:fs";
25	import { join } from "node:path";
26	import { describe, expect, it } from "vitest";
27	
28	/** Every file of a kind in the tree, by the path the rules below name it by. */
29	function everyFile(from: string, ending: readonly string[]): Record<string, string> {
30	  const found: Record<string, string> = {};
31	  for (const name of readdirSync(from)) {
32	    const path = join(from, name);
33	    if (statSync(path).isDirectory()) {
34	      Object.assign(found, everyFile(path, ending));
35	    } else if (ending.some((one) => name.endsWith(one))) {
36	      found[`/${path.replaceAll("\\", "/")}`] = readFileSync(path, "utf8");
37	    }
38	  }
39	  return found;
40	}
41	
42	const STYLESHEETS = everyFile("src", [".css"]);
43	const COMPONENTS = everyFile("src", [".tsx", ".ts"]);
44	
45	/**
46	 * The only property an animation in this product is allowed to change.
47	 *
48	 * Everything else is a movement, and the motion budget has three movements in it
49	 * — the propagation wave, a branch arriving, and a likelihood rolling from an old
50	 * figure to a new one — none of which is a thing pretending to be busy.
51	 */
52	const THE_ONE_PROPERTY = "opacity";
53	
54	/** Every `@keyframes` block in a stylesheet, with the name it goes by. */
55	function keyframesIn(sheet: string): { name: string; body: string }[] {
56	  const found: { name: string; body: string }[] = [];
57	  const at = /@keyframes\s+([\w-]+)\s*\{/g;
58	  let match = at.exec(sheet);
59	  while (match !== null) {
60	    // Walk from the opening brace to the one that closes it, counting depth, so
61	    // the nested `from {}` and `to {}` blocks are kept with their own rule.
62	    let depth = 1;
63	    let place = at.lastIndex;
64	    while (place < sheet.length && depth > 0) {
65	      if (sheet[place] === "{") {
66	        depth += 1;
67	      } else if (sheet[place] === "}") {
68	        depth -= 1;
69	      }
70	      place += 1;
71	    }
72	    found.push({ name: match[1] ?? "", body: sheet.slice(at.lastIndex, place - 1) });
73	    at.lastIndex = place;
74	    match = at.exec(sheet);
75	  }
76	  return found;
77	}
78	
79	/**
80	 * One module with its comments taken out.
81	 *
82	 * The words below are looked for in the **code**, not in the prose around it —
83	 * half this product's files explain in so many words why there is no spinner in
84	 * them, and a check that failed on those would be a check that punished saying so.
85	 */
86	function withoutComments(source: string): string {
87	  return source.replaceAll(/\/\*[\s\S]*?\*\//g, " ").replaceAll(/\/\/[^\n]*/g, " ");
88	}
89	
90	/** Every property a block of rules sets, by name. */
91	function propertiesIn(body: string): string[] {
92	  return [...body.matchAll(/(^|[{;\s])([a-z-]+)\s*:/g)]
93	    .map((one) => one[2] ?? "")
94	    .filter((one) => one !== "" && !one.startsWith("--"));
95	}
96	
97	describe("there is no spinner anywhere", () => {
98	  it("test_there_is_no_spinner_anywhere", () => {
99	    const wrong: string[] = [];
100	
101	    for (const [path, sheet] of Object.entries(STYLESHEETS)) {
102	      // A check that silently walks nothing is a check that always passes.
103	      expect(sheet.length).toBeGreaterThan(0);
104	
105	      for (const { name, body } of keyframesIn(sheet)) {
106	        for (const property of propertiesIn(body)) {
107	          if (property !== THE_ONE_PROPERTY) {
108	            wrong.push(`${path}: @keyframes ${name} changes ${property}`);
109	          }
110	        }
111	      }
112	
113	      // Nothing loops. A loop is the whole of what a spinner is.
114	      for (const declaration of sheet.matchAll(/animation[^;]*;/g)) {
115	        const said = declaration[0];
116	        if (said.includes("infinite") || /animation-iteration-count/.test(said)) {
117	          wrong.push(`${path}: ${said.trim()} loops`);
118	        }
119	      }
120	    }
121	
122	    for (const [path, whole] of Object.entries(COMPONENTS)) {
123	      if (path.includes("__tests__")) {
124	        continue;
125	      }
126	      const source = withoutComments(whole);
127	      if (source.includes('role="progressbar"') || source.includes("'progressbar'")) {
128	        wrong.push(`${path}: renders an indeterminate progress indicator`);
129	      }
130	      for (const word of ["spinner", "Spinner", "loader", "Loader", "isLoading"]) {
131	        if (source.includes(word)) {
132	          wrong.push(`${path}: names a ${word}`);
133	        }
